package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.nio.file.Path;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.CleanupMode;
import org.junit.jupiter.api.io.TempDir;

/** Existing owner/close APIs only: no witness, qualification, prepared-certificate or new test helper API. */
class LmdbSailStoreTerminalCloseTest {
	@TempDir(cleanup = CleanupMode.NEVER)
	Path directory;

	@Test
	void repeatedSuccessfulOwnerCloseCannotTouchLaterGeneration() throws Exception {
		var values = SimpleValueFactory.getInstance();
		var predicate = values.createIRI("urn:terminal-close:predicate");
		var firstSubject = values.createIRI("urn:terminal-close:first");
		var secondSubject = values.createIRI("urn:terminal-close:second");
		var object = values.createLiteral("committed");
		var config = new LmdbStoreConfig("spoc,posc").setForceSync(true).setSketchEstimatorEnabled(false);
		LmdbStore firstStore = new LmdbStore(directory.toFile(), config);
		SailRepository first = new SailRepository(firstStore);
		first.init();
		LmdbSailStore firstOwner = firstStore.getBackingStore();
		try (var connection = first.getConnection()) {
			connection.begin();
			connection.add(firstSubject, predicate, object);
			connection.commit();
		} finally {
			first.shutDown();
		}
		LmdbStore secondStore = new LmdbStore(directory.toFile(), config);
		SailRepository second = new SailRepository(secondStore);
		second.init();
		try (var connection = second.getConnection()) {
			connection.begin();
			connection.add(secondSubject, predicate, object);
			connection.commit();
			assertEquals(2L, connection.size());
		} finally {
			second.shutDown();
		}
		byte[] laterProperties = Files.readAllBytes(directory.resolve("store.properties"));
		assertDoesNotThrow(firstOwner::close,
				"a successfully closed owner has no native or persistent work left for a later generation");
		assertArrayEquals(laterProperties, Files.readAllBytes(directory.resolve("store.properties")),
				"the terminal owner cannot overwrite the later owner's properties");
		LmdbStore reopenedStore = new LmdbStore(directory.toFile(), config);
		SailRepository reopened = new SailRepository(reopenedStore);
		reopened.init();
		try (var connection = reopened.getConnection()) {
			assertEquals(2L, connection.size());
			assertTrue(connection.hasStatement(firstSubject, predicate, object, false));
			assertTrue(connection.hasStatement(secondSubject, predicate, object, false));
		} finally {
			reopened.shutDown();
		}
	}
}
